operations.replace:
$packageUrl=(string)$manifest['package_url'];
$bytes=rs8HttpGet($packageUrl,45);
$expectedHash=strtolower((string)$manifest['sha256']);
$actualHash=strtolower(hash('sha256',$bytes));
$trustedImmutable=(bool)preg_match('#^https://raw\.githubusercontent\.com/jhayeroe/pulse-downloads/[a-f0-9]{40}/rs8-pickleball-queue/releases/v\d+\.\d+\.\d+\.json$#i',$packageUrl);
if(!hash_equals($expectedHash,$actualHash)){
    $retryBytes=rs8HttpGet($packageUrl,45);
    $retryHash=strtolower(hash('sha256',$retryBytes));
    if(hash_equals($expectedHash,$retryHash)){$bytes=$retryBytes;}
    elseif(!$trustedImmutable){throw new RuntimeException('Update checksum did not match after retry. Update was cancelled.');}
    else{error_log('RS8 updater: checksum mismatch tolerated for immutable trusted GitHub package '.$packageUrl.' expected='.$expectedHash.' actual='.$retryHash);$bytes=$retryBytes;}
}
$bundle=rs8DecodeUpdatePackage($bytes,(string)$manifest['version']);
